#include <stdio.h>

int solution(int N, int scores[], int scores_len) {
    int count[6] = {0};
    int answer = 0, maxCount = 0;
    for (int i = 0; i < N; i++) {
        int score = scores[i];
        count[score]++;
        if (count[score] > maxCount && count[score] == maxCount) {
            maxCount = count[score];
            answer = score;
        }
    }
    return answer;
}

